// Field order matches a3d::Font. Each value is on its own line with its
// name, because an aggregate initialiser is silently wrong when two
// adjacent fields of the same type are swapped.
inline constexpr Font kFont12x21 = {
    12,    // w
    21,    // h
    12,    // advance
    16,    // ascent
    32,    // first
    126,   // last
    2,     // stride
    kFont12x21Bits,
    };

